    'RegisterSimpleRisk'=>'SimpleRisk रजिस्टर',
    'RegistrationText'=>'पंजीकृत सिंपल रिस्क इंस्टेंस को तुरंत अपग्रेड एंड सिक्योर कंट्रोल फ्रेमवर्क (SCF) एक्स्ट्रा तक पहुंच प्रदान की जाती है। अपग्रेड एक्स्ट्रा एक बटन के क्लिक के साथ आपके सिंपल रिस्क इंस्टेंस को बैकअप और अपग्रेड करने की क्षमता प्रदान करता है। सिक्योर कंट्रोल फ्रेमवर्क (SCF) एक्स्ट्रा एक सामान्य नियंत्रण ढांचा प्रदान करता है जिसे SimpleRisk गवर्नेंस कार्यक्षमता में एकीकृत किया गया है। SimpleRisk को पंजीकृत करने पर, आपकी पंजीकरण जानकारी SimpleRisk द्वारा होस्ट किए गए सर्वर को भेजी जाएगी। प्रदान की गई पंजीकरण जानकारी का उपयोग सिंपल रिस्क द्वारा ग्राहकों को नए रिलीज और सुरक्षा अपडेट के बारे में सूचित करने के लिए किया जाएगा। SimpleRisk को पंजीकृत करने का कार्य आपको हमारे मार्केटिंग संचार में शामिल करेगा, लेकिन आप इन संचारों में सदस्यता समाप्त लिंक का उपयोग करके किसी भी समय बाहर निकल सकते हैं। SimpleRisk हमारे ग्राहकों की गोपनीयता का सम्मान करता है और SimpleRisk पंजीकरण प्रक्रिया के माध्यम से हमें प्रदान की गई जानकारी कभी भी किसी तीसरे पक्ष को नहीं बेची जाएगी।',
