    'ActivatingSCFMessage' => 'सिक्योर कंट्रोल्स फ्रेमवर्क (SCF) फ्रेमवर्क इंस्टॉल किया जा रहा है।\n\nसिस्टम के प्रदर्शन और चयनित फ्रेमवर्क की संख्या के आधार पर, इसमें एक घंटे तक का समय लग सकता है।\n\nबैकग्राउंड में प्रक्रिया जारी रहने के दौरान आप इस पेज से बाहर जा सकते हैं।',
    'DeactivatingSCFMessage' => 'सिक्योर कंट्रोल्स फ्रेमवर्क (SCF) फ्रेमवर्क को अनइंस्टॉल किया जा रहा है।\n\nसिस्टम के प्रदर्शन और चयनित फ्रेमवर्क की संख्या के आधार पर, इसमें एक घंटे तक का समय लग सकता है।\n\nपृष्ठभूमि में प्रक्रिया जारी रहने के दौरान आप इस पृष्ठ से बाहर जा सकते हैं।',
    'UpdatingSCFMessage' => 'सिक्योर कंट्रोल्स फ्रेमवर्क (SCF) फ्रेमवर्क को अपडेट किया जा रहा है।\n\nसिस्टम के प्रदर्शन और चयनित फ्रेमवर्क की संख्या के आधार पर, इसमें एक घंटे तक का समय लग सकता है।\n\nपृष्ठभूमि में प्रक्रिया जारी रहने के दौरान आप इस पृष्ठ से बाहर जा सकते हैं।',
