    'AdminRoleDescription' => 'यह अनुमति सरलरिस्क के विन्यास तक पहुंच प्रदान करती है। इस अनुमति के साथ एक उपयोगकर्ता प्रभावी रूप से सिस्टम पर एक प्रशासनिक उपयोगकर्ता है। वे "कॉन्फ़िगर" मेनू में पाए जाने वाले किसी भी और सभी मेनू में परिवर्तन करने में सक्षम हैं। यह एक्स्ट्रा कलाकार के सक्रियण और डी-एक्टिवेशन और उनके कॉन्फ़िगरेशन को संशोधित करने की भी अनुमति देगा। यह अनुमति केवल उन्हीं लोगों को दी जानी चाहिए जिन्हें इसकी नितांत आवश्यकता है। एक बार जब किसी उपयोगकर्ता के पास इस अनुमति तक पहुंच हो जाती है तो वे अन्य उपयोगकर्ता खातों को भी संपादित करने में सक्षम होंगे।',
